<?php
namespace App\Http\Controllers;
use App\Contracts\D1ServiceInterface; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class UserController extends Controller { public function __construct(private D1ServiceInterface $d1) {} public function index() { return response()->json(['data'=>$this->d1->users()]); } public function store(Request $r): RedirectResponse { $d=$r->validate(['name'=>'required|string|max:100','password'=>'required|string|min:8','role'=>'required|in:admin,cashier']); $d['password']=Hash::make($d['password']); $this->d1->createUser($d); return back()->with('success','Akun dibuat.'); } public function update(Request $r,int $user): RedirectResponse { $d=$r->validate(['name'=>'required|string|max:100','password'=>'nullable|string|min:8','role'=>'required|in:admin,cashier']); if(!empty($d['password']))$d['password']=Hash::make($d['password']); $this->d1->updateUser($user,$d); return back()->with('success','Akun diperbarui.'); } public function destroy(int $user): RedirectResponse { $this->d1->deleteUser($user); return back()->with('success','Akun dihapus.'); } }
